body { margin: 0; font-family: -apple-system, 'Segoe UI', Roboto, sans-serif; background: transparent; }
.cards { display: flex; flex-direction: column; gap: 18px; padding: 4px; }
.card { border: 1px solid #e2e8f0; border-radius: 6px; overflow: hidden; background: #fff; }
.card-header { display: flex; justify-content: space-between; align-items: center; background: #0b1f44; color: #fff; padding: 10px 16px; font-weight: 600; font-size: 14px; }
.card-header .title { flex: 1; }
.card-header .total { font-size: 16px; }
.card-body table { width: 100%; border-collapse: collapse; font-size: 13px; table-layout: fixed; }
.card-body th, .card-body td { padding: 8px 12px; text-align: left; overflow: hidden; text-overflow: ellipsis; }
.card-body th:nth-child(1), .card-body td:nth-child(1) { width: 52%; }
.card-body th:nth-child(2), .card-body td:nth-child(2) { width: 18%; }
.card-body th:nth-child(3), .card-body td:nth-child(3) { width: 15%; }
.card-body th:nth-child(4), .card-body td:nth-child(4) { width: 15%; }
.card-body td.num, .card-body th.num { text-align: right; font-variant-numeric: tabular-nums; }
.card-scroll { max-height: 280px; overflow-y: auto; }
.card-scroll thead th { position: sticky; top: 0; background: #f8fafc; color: #475569; font-weight: 500; border-bottom: 1px solid #e2e8f0; z-index: 1; }
.card-scroll tr.line { border-bottom: 1px solid #f1f5f9; }
.card-summary { border-top: 2px solid #e2e8f0; background: #fafbfc; }
.card-summary tr.summary { font-weight: 600; }
.card-summary tr.summary td { border-top: 1px solid #e2e8f0; }
.card-summary tr.summary:first-child td { border-top: none; }
.card-body .err { padding: 12px 16px; color: #b91c1c; background: #fef2f2; font-size: 13px; }

