function fmt(n) {
  if (n == null || isNaN(n)) return '';
  const v = Number(n);
  return (v < 0 ? '-' : '') + '$' + Math.abs(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function fmtRate(r) {
  if (r == null || r === '') return '';
  const v = Number(r);
  if (isNaN(v)) return String(r);
  return (v < 0 ? '-' : '') + '$' + Math.abs(v).toFixed(4);
}

function fmtQty(q, unit) {
  if (q == null || q === '') return '';
  const n = Number(q);
  if (isNaN(n)) return String(q);
  const s = n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return unit ? `${s} ${unit}` : s;
}

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function renderCard(b) {
  const title = `${escapeHtml(b.lseName || '')} | ${escapeHtml(b.tariffName || '')} | ${escapeHtml(b.serviceType || '')}`;
  const total = fmt(b.adjustedTotalCost);
  let body;
  if (b.error) {
    body = `<div class="err">Calculate failed: ${escapeHtml(b.error)}</div>`;
  } else {
    const lineRows = (b.lines || []).map(l => `
      <tr class="line">
        <td>${escapeHtml(l.name)}</td>
        <td class="num">${escapeHtml(fmtQty(l.qty, l.qty_unit))}</td>
        <td class="num">${escapeHtml(fmtRate(l.rate))}</td>
        <td class="num">${escapeHtml(fmt(l.cost))}</td>
      </tr>`).join('');
    body = `
      <div class="card-scroll">
        <table>
          <thead><tr>
            <th>Charge</th><th class="num">QTY</th><th class="num">Rate</th><th class="num">Cost</th>
          </tr></thead>
          <tbody>${lineRows}</tbody>
        </table>
      </div>
      <div class="card-summary">
        <table>
          <tbody>
            <tr class="summary"><td colspan="3">Sub Total Cost</td><td class="num">${fmt(b.subTotalCost)}</td></tr>
            <tr class="summary"><td colspan="3">Non Bypassable Cost</td><td class="num">${fmt(b.nonBypassableCost)}</td></tr>
            <tr class="summary"><td colspan="3">Tax Cost</td><td class="num">${fmt(b.taxCost)}</td></tr>
          </tbody>
        </table>
      </div>`;
  }
  return `
    <div class="card">
      <div class="card-header"><div class="title">${title}</div><div class="total">${total}</div></div>
      <div class="card-body">${body}</div>
    </div>`;
}

function render(model) {
  const blocks = Array.isArray(model && model.blocks) ? model.blocks : [];
  const root = document.getElementById('root');
  if (!root) return;
  if (!blocks.length) {
    root.innerHTML = '<div style="padding:16px;color:#64748b;font-size:13px">No results yet. Pick tariffs and click Calculate.</div>';
    return;
  }
  root.innerHTML = blocks.map(renderCard).join('');
}

appsmith.onReady(() => {
  render(appsmith.model);
  appsmith.onModelChange(render);
});

